-- AURA catalogue schema, shared by SQLite (#18) and PostgreSQL (#19).
-- Column types use TEXT/INTEGER/portable across both engines.
--
-- Identifiers (`id` and every `*_id` foreign key) hold canonical UUID v4 text:
-- lowercase, 8-4-4-4-12, generated by api/ids.py. No table-level CHECK is added
-- because SQLite cannot attach one to an existing table (it would apply to fresh
-- installs only); the format is enforced at the API boundary and by the seed in
-- api/migrations.py. See docs/DATA-MODEL.md.
--
-- Base tables (users, sessions, folders, objects) plus the multi-platform model
-- (#35: applications, spaces, buckets) and machine-to-machine identities (#38).
-- Additive columns on `users` and `objects` are applied by api/migrations.py, so
-- an existing catalogue keeps its data (see docs/AUTHORIZATION-MATRIX.md).
CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY,
  username TEXT UNIQUE NOT NULL,
  pass_hash TEXT NOT NULL,
  created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS sessions (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id),
  csrf TEXT NOT NULL,
  expires_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS folders (
  id TEXT PRIMARY KEY,
  owner_id TEXT NOT NULL REFERENCES users(id),
  parent_id TEXT REFERENCES folders(id),
  name TEXT NOT NULL,
  created_at INTEGER NOT NULL
);
-- owner_id is nullable: objects created by a service identity (#38) have no
-- human owner, but always carry a space_id (#35) and an actor_id/actor_kind.
CREATE TABLE IF NOT EXISTS objects (
  id TEXT PRIMARY KEY,
  bucket TEXT NOT NULL,
  object_key TEXT NOT NULL,
  display_name TEXT NOT NULL,
  content_type TEXT NOT NULL,
  size_bytes BIGINT NOT NULL DEFAULT -1,
  checksum_sha256 TEXT NOT NULL DEFAULT '',
  folder_id TEXT REFERENCES folders(id),
  owner_id TEXT REFERENCES users(id),
  visibility TEXT NOT NULL DEFAULT 'private',
  status TEXT NOT NULL DEFAULT 'pending',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  -- Publication (admin Publish panel): a stable slug the operator can keep
  -- across content replacements, and its publication timestamp.
  public_slug TEXT,
  published_at INTEGER,
  -- Generated preview metadata (video poster / image thumbnail, duration).
  thumbnail_key TEXT,
  duration_seconds REAL,
  UNIQUE (bucket, object_key)
);
CREATE TABLE IF NOT EXISTS applications (
  id TEXT PRIMARY KEY,
  name TEXT UNIQUE NOT NULL,
  status TEXT NOT NULL DEFAULT 'active',
  created_at INTEGER NOT NULL
);
-- `status` is a soft lifecycle flag (active/disabled). A space is never deleted
-- through the API: disabling it stops new identities and new uploads while the
-- existing catalogue rows stay readable (#M04). Added additively on upgrades.
CREATE TABLE IF NOT EXISTS spaces (
  id TEXT PRIMARY KEY,
  application_id TEXT NOT NULL REFERENCES applications(id),
  name TEXT NOT NULL,
  environment TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active',
  created_at INTEGER NOT NULL,
  UNIQUE (application_id, name, environment)
);
CREATE TABLE IF NOT EXISTS buckets (
  id TEXT PRIMARY KEY,
  space_id TEXT NOT NULL REFERENCES spaces(id),
  name TEXT UNIQUE NOT NULL,
  is_default INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS service_identities (
  id TEXT PRIMARY KEY,
  application_id TEXT NOT NULL REFERENCES applications(id),
  space_id TEXT NOT NULL REFERENCES spaces(id),
  name TEXT NOT NULL,
  secret_hash TEXT NOT NULL,
  scopes TEXT NOT NULL DEFAULT '',
  role TEXT NOT NULL DEFAULT 'service',
  created_at INTEGER NOT NULL,
  expires_at INTEGER,
  last_used_at INTEGER,
  revoked_at INTEGER,
  rotated_at INTEGER
);
-- Public share links: an unauthenticated, revocable, read-only capability for
-- exactly one object. Only the SHA-256 fingerprint of the link token is stored,
-- so a catalogue dump cannot be replayed as working links. `space_id` is copied
-- from the object at creation so the redemption path can attribute the access to
-- a tenant without a join, and `created_by` keeps attribution even if the creator
-- later loses the role. Rows are never deleted -- revocation is a timestamp, so
-- an audit entry always resolves to a real row. `max_uses` is enforced atomically
-- by Repository.consume_share.
--
-- No foreign key on object_id on purpose: `objects:purge` removes the object row
-- (api/lifecycle.py) and a share must then be a harmless dangling row that
-- answers 404, never a constraint that blocks a purge. Lifecycle deletes the
-- share rows explicitly, before the object row.
CREATE TABLE IF NOT EXISTS object_shares (
  id TEXT PRIMARY KEY,
  object_id TEXT NOT NULL,
  space_id TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_by_kind TEXT NOT NULL,
  token_hash TEXT NOT NULL UNIQUE,
  content_disposition TEXT NOT NULL DEFAULT 'attachment',
  expires_at INTEGER NOT NULL,
  max_uses INTEGER,
  use_count INTEGER NOT NULL DEFAULT 0,
  revoked_at INTEGER,
  last_used_at INTEGER,
  created_at INTEGER NOT NULL
);
-- Partner integrations (admin console "Intégrations"). One row per external
-- site (course platform, intranet, ...) that consumes one space through its own
-- service identity. The identity remains the credential: rotation/revocation
-- still happen on `service_identities`, so this table only carries the trust
-- metadata an operator needs (site origin, default media TTL, notes). Deleting
-- the identity leaves the row as history; it is never used for authentication.
CREATE TABLE IF NOT EXISTS partner_sites (
  id TEXT PRIMARY KEY,
  space_id TEXT NOT NULL REFERENCES spaces(id),
  identity_id TEXT NOT NULL REFERENCES service_identities(id),
  name TEXT NOT NULL,
  site_url TEXT NOT NULL,
  default_ttl_seconds INTEGER,
  notes TEXT NOT NULL DEFAULT '',
  created_by TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE (space_id, name)
);
-- Per-space monthly quotas (admin "Consommation"). Null means "no quota", not
-- zero: zero would block every upload. Storage is enforced at upload intent;
-- egress is an estimate derived from issued intents and share redemptions,
-- because AURA never proxies object bytes.
CREATE TABLE IF NOT EXISTS space_quotas (
  space_id TEXT PRIMARY KEY REFERENCES spaces(id),
  storage_bytes BIGINT,
  egress_bytes_monthly BIGINT,
  updated_at INTEGER NOT NULL,
  updated_by TEXT
);
-- Monthly usage per space. Egress is counted when an intent is issued or a
-- share is redeemed (`size_bytes` of the object), so it is a planning estimate,
-- not an edge measurement. Rows are additive and never rewritten negatively.
CREATE TABLE IF NOT EXISTS space_usage_monthly (
  space_id TEXT NOT NULL REFERENCES spaces(id),
  period TEXT NOT NULL,
  egress_bytes BIGINT NOT NULL DEFAULT 0,
  download_intents INTEGER NOT NULL DEFAULT 0,
  preview_intents INTEGER NOT NULL DEFAULT 0,
  share_redemptions INTEGER NOT NULL DEFAULT 0,
  updated_at INTEGER NOT NULL,
  PRIMARY KEY (space_id, period)
);
-- Content revisions (docs/CONTENT-REVISIONS.md). One row per archived version of
-- an object; the live bytes stay on `objects.object_key` and each revision owns
-- its own `storage_key`. Bytes are copied by the application, never by S3 native
-- bucket versioning: the reconciliation model assumes exactly one live key per
-- object, so S3-managed old versions would be misread as storage orphans.
--
-- `ON DELETE RESTRICT` on object_id is deliberate and is the reason phase 2 must
-- change the purge path: deleting an object row while its revisions still exist
-- has to be an explicit, ordered operation, never a cascade that could drop the
-- row and leave the bytes unaccounted. Nothing writes this table yet (phase 1 is
-- schema only).
CREATE TABLE IF NOT EXISTS object_revisions (
  id TEXT PRIMARY KEY,
  object_id TEXT NOT NULL REFERENCES objects(id) ON DELETE RESTRICT,
  revision_number INTEGER NOT NULL,
  bucket TEXT NOT NULL,
  storage_key TEXT NOT NULL,
  size_bytes INTEGER NOT NULL,
  checksum_sha256 TEXT NOT NULL DEFAULT '',
  content_type TEXT NOT NULL DEFAULT 'application/octet-stream',
  created_at INTEGER NOT NULL,
  created_by_id TEXT,
  created_by_kind TEXT,
  keep_forever INTEGER NOT NULL DEFAULT 0,
  purged_at INTEGER,
  UNIQUE (object_id, revision_number)
);
CREATE TABLE IF NOT EXISTS schema_migrations (
  id TEXT PRIMARY KEY,
  applied_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_objects_owner ON objects(owner_id, status);
CREATE INDEX IF NOT EXISTS idx_identities_space ON service_identities(space_id);
CREATE INDEX IF NOT EXISTS idx_partner_sites_space ON partner_sites(space_id);
CREATE INDEX IF NOT EXISTS idx_space_usage_period ON space_usage_monthly(period);
CREATE INDEX IF NOT EXISTS idx_shares_object ON object_shares(object_id);
-- Revision indexes: list one object's history, find the bytes behind a revision
-- during orphan/reconcile scans (must NOT be mistaken for storage orphans), and
-- let the retention sweep find candidates without scanning the table.
CREATE INDEX IF NOT EXISTS idx_revisions_object ON object_revisions(object_id, revision_number);
CREATE INDEX IF NOT EXISTS idx_revisions_storage ON object_revisions(bucket, storage_key);
CREATE INDEX IF NOT EXISTS idx_revisions_keep ON object_revisions(keep_forever) WHERE keep_forever = 1;
CREATE INDEX IF NOT EXISTS idx_revisions_purge ON object_revisions(purged_at, created_at) WHERE purged_at IS NULL;
-- idx_objects_space is created by api/migrations.py, after the additive
-- `space_id` column exists on upgraded catalogues.
-- Object tags (free-form, normalized) and ordered course packs. No foreign keys
-- on object_id on purpose: an object purge must never be blocked by metadata;
-- lifecycle deletes these rows explicitly before removing the object.
CREATE TABLE IF NOT EXISTS object_tags (
  object_id TEXT NOT NULL,
  tag TEXT NOT NULL,
  PRIMARY KEY (object_id, tag)
);
CREATE TABLE IF NOT EXISTS collections (
  id TEXT PRIMARY KEY,
  space_id TEXT NOT NULL,
  owner_id TEXT,
  slug TEXT NOT NULL,
  title TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  published_at INTEGER,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE (slug)
);
CREATE TABLE IF NOT EXISTS collection_items (
  collection_id TEXT NOT NULL,
  object_id TEXT NOT NULL,
  position INTEGER NOT NULL,
  PRIMARY KEY (collection_id, object_id)
);
CREATE INDEX IF NOT EXISTS idx_object_tags_tag ON object_tags(tag);
CREATE INDEX IF NOT EXISTS idx_collection_items_pos ON collection_items(collection_id, position);
